def _umap_embedding_tsv(umap: UmapResult, clustering: KMeansResult) -> str:
    """逐细胞二维嵌入坐标：细胞顺序与 pca_scatter.tsv 一致，cluster 为最终簇标签。"""
    lines = [tsv_row(["cell_id", "UMAP1", "UMAP2", "cluster"])]
    for c, cell_id in enumerate(umap.cell_ids):
        lines.append(
            tsv_row(
                [
                    cell_id,
                    fmt_float(umap.embedding[c][0]),
                    fmt_float(umap.embedding[c][1]),
                    clustering.labels[c],
                ]
            )
        )
    return "\n".join(lines) + "\n"


def _umap_neighbors_tsv(umap: UmapResult) -> str:
    """每个细胞的有向邻域记录：源细胞按 pca_scatter.tsv 顺序，每个源细胞的
    邻居按 weight 降序、neighbor_id 升序排列（统计模块已定序），rank 自 1 起。"""
    lines = [tsv_row(["cell_id", "neighbor_id", "weight", "rank"])]
    for i, cell_id in enumerate(umap.cell_ids):
        for rank, (j, weight) in enumerate(umap.neighbors[i], start=1):
            lines.append(
                tsv_row([cell_id, umap.cell_ids[j], fmt_float(weight), rank])
            )
    return "\n".join(lines) + "\n"


